PROGRAM ST_H02_OVERLAMNING
VAR
    steg      : INT := 0;
    tmrHold   : TON;
    tmrClosed : TON;
    forceOk   : BOOL := FALSE;
END_VAR

tmrClosed(IN := (steg = 2), PT := T#1500ms);
tmrHold(IN := (steg = 3), PT := T#200ms);

forceOk := (ST320_GRP_FORCE >= 80.0) AND (ST320_GRP_FORCE <= 300.0);

IF NOT EMG_OK OR NOT AIR_OK THEN
    ST310_HS_REQ    := FALSE;
    ST310_GRP_OPEN  := FALSE;
    ST310_HS_RST    := FALSE;
    ST320_GRP_CLOSE := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            IF EMG_OK AND AIR_OK THEN
                steg := 1;
            END_IF;
        1:
            ST310_HS_RST := FALSE;
            ST310_GRP_OPEN := FALSE;
            ST310_HS_REQ := TRUE;
            IF ST320_HS_ACK THEN
                steg := 2;
            END_IF;
        2:
            ST320_GRP_CLOSE := TRUE;
            IF ST320_GRP_CLOSED AND forceOk THEN
                steg := 3;
            ELSIF tmrClosed.Q OR (ST320_GRP_CLOSED AND NOT forceOk) THEN
                steg := 9;
            END_IF;
        3:
            IF tmrHold.Q THEN
                ST310_GRP_OPEN := TRUE;
                steg := 4;
            END_IF;
        4:
            IF ST310_GRP_OPENED AND ST320_HS_DONE THEN
                ST310_HS_REQ := FALSE;
                ST310_HS_RST := TRUE;
                steg := 5;
            END_IF;
        5:
            IF NOT ST320_HS_DONE THEN
                ST310_HS_RST := FALSE;
                ST310_GRP_OPEN := FALSE;
                ST320_GRP_CLOSE := FALSE;
                steg := 1;
            END_IF;
        9:
            ST310_GRP_OPEN := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

